package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.EntityType;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsRural092 {
 @GameTest(template="empty") public static void cookedMeatRescuesButRawDoesNot(GameTestHelper h){var p=CityTestsRural.person();p.nourishment=4;var stock=new RuralRules.Stock();stock.raw[0]=8;RuralRules.meal(List.of(p),List.of(stock));h.assertTrue(p.nourishment==2&&stock.raw[0]==8,"Raw meat is not free ready food");RuralMeat.cook(List.of(stock),2,8);RuralRules.meal(List.of(p),List.of(stock));h.assertTrue(!p.dead&&p.nourishment==2&&stock.cooked[0]==0&&stock.raw[0]==6,"Cooked meat prevents starvation and is consumed exactly once");h.succeed();}
 @GameTest(template="empty") public static void inventoryPriceAndSmallCoinConservation(GameTestHelper h){var pol=RuralMarket.defaults(0);pol.target=40;pol.markup=20;pol.discount=20;h.assertTrue(RuralMarket.quoteTenths(pol,0,2)==24&&RuralMarket.quoteTenths(pol,10,2)==22&&RuralMarket.quoteTenths(pol,40,2)==20&&RuralMarket.quoteTenths(pol,70,2)==18,"Continuous stock model matches worked example");var d=new RuralSettlement();var seller=CityTestsRural.person();var buyer=CityTestsRural.person();var f=CityTestsRural.family(buyer);f.city=UUID.randomUUID();d.state.families.put(f.id,f);var head=buyer;head.market.put(0,pol);var source=new RuralRules.Stock();source.wheat=10;var target=new RuralRules.Stock();var money=new HashMap<UUID,Long>();money.put(buyer.id,50L);money.put(seller.id,50L);int n=RuralMarket.buy(d,head,f,seller.id,List.of(source),List.of(target),0,10,2,money);h.assertTrue(n==10&&money.values().stream().mapToLong(Long::longValue).sum()==100&&source.wheat+target.wheat==10,"Goods and whole silver conserved");var saved=CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(d.state),RuralSettlement.State.class);h.assertTrue(saved.priceRemainders.equals(d.state.priceRemainders),"Small-coin debt survives restart");h.succeed();}
 @GameTest(template="empty") public static void externalBuyerLeavesLocalMealsAndAuditsMoney(GameTestHelper h){var d=new RuralSettlement();var p=CityTestsRural.person();p.role=RuralRules.Role.MERCHANT;var f=CityTestsRural.family(p);f.city=UUID.randomUUID();d.state.families.put(f.id,f);d.state.people.put(p.id,p);d.state.externalBuyer.add(f.city);for(int i=0;i<2;i++){var box=new RuralSettlement.Box();box.linked=true;box.stock.family=f.id;box.stock.wheat=10;d.state.boxes.put("b"+i,box);}p.market.put(0,RuralMarket.defaults(0));p.market.get(0).target=4;var money=new HashMap<UUID,Long>();money.put(p.id,50L);RuralMarket.export(d,f.city,List.of(f),f,p,money);h.assertTrue(RuralRules.count(d.stocks(f.id),false)==4,"Head next two meals protected");h.assertTrue(d.audit(f.city).exportWheat==16&&money.get(p.id)==50+d.audit(f.city).externalSilver,"Export goods and explicit outside silver match");h.succeed();}
 @GameTest(template="empty") public static void fullBarnRetainsMatureWheat(GameTestHelper h){var s=h.getLevel().getServer();var d=new RuralSettlement();var p=CityTestsRural.person();p.role=RuralRules.Role.FARMER;p.trainedHours=10;p.pendingWheat=20;var f=CityTestsRural.family(p);f.city=UUID.randomUUID();d.state.people.put(p.id,p);d.state.families.put(f.id,f);var job=new RuralSettlement.Site();job.worker=p.id;d.state.sites.put("s",job);var box=new RuralSettlement.Box();box.city=f.city;box.linked=true;box.stock.family=f.id;box.stock.wheat=10;d.state.boxes.put("b",box);var city=new CityData.City(f.city,UUID.randomUUID(),"吞麦回归",h.getLevel().dimension().location().toString(),CityBounds.between(h.absolutePos(net.minecraft.core.BlockPos.ZERO),h.absolutePos(new net.minecraft.core.BlockPos(2,2,2))));d.cycle(s,city,false,false);h.assertTrue(p.pendingWheat==20,"Full barn and no buyer retains the entire crop");box.stock.wheat=3;d.cycle(s,city,false,false);h.assertTrue(p.pendingWheat==13&&box.stock.wheat==10&&d.audit(f.city).wheatHarvested==7,"Available space harvests only seven, leaving thirteen in the field");CityEconomy.get(s).state.accounts.remove(CityEconomy.person(p.id));h.succeed();}
}
